import os

def clean_path(p):
    """パスのクリーニングを行う"""
    return p

def get_file_info(p):
    """ファイル情報を取得する"""
    return os.path.basename(p)

def list_files(directory):
    """ディレクトリ内のファイル一覧を返す"""
    return os.listdir(directory)
